:root {
  --bg: #1a1c2c;
  --panel: #29366f;
  --text: #f4f4f4;
  --accent: #f4b41b;
  --correct: #41a6f6;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 18px;
  padding: 16px;
}
.card {
  background: var(--panel);
  border: 4px solid var(--accent);
  box-shadow: 8px 8px 0 #0d0e17;
  padding: 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
}
h1 {
  margin: 0 0 16px;
  font-size: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}
#question {
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 24px;
  min-height: 40px;
}
.answers, .actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 16px;
}
button {
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  padding: 12px 20px;
  min-width: 100px;
  border: 3px solid var(--accent);
  background: var(--bg);
  color: var(--text);
  box-shadow: 4px 4px 0 #0d0e17;
  transition: transform 0.05s, box-shadow 0.05s;
}
button:hover { background: #22253a; }
button:focus-visible {
  outline: 3px solid var(--correct);
  outline-offset: 2px;
}
button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}
button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
  box-shadow: 4px 4px 0 #0d0e17;
}
.score-line { margin: 0 0 20px; }
#score { color: var(--accent); font-weight: 700; }
#next, #restart { min-width: 110px; }
@media (max-width: 400px) {
  .answers, .actions { flex-direction: column; align-items: stretch; }
  button { width: 100%; }
}

const questions = [
  { text: "2 + 2 = ?", a: "4", b: "5", correct: "a" },
  { text: "3 + 3 = ?", a: "5", b: "6", correct: "b" }
];

const questionEl = document.getElementById("question");
const answerA = document.getElementById("answer-a");
const answerB = document.getElementById("answer-b");
const scoreEl = document.getElementById("score");
const nextBtn = document.getElementById("next");
const restartBtn = document.getElementById("restart");

let index = 0;
let score = 0;
let locked = false;
let finished = false;

function render() {
  const q = questions[index];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  locked = false;
  finished = false;
  scoreEl.textContent = String(score);
}

function answer(choice) {
  if (locked || finished) return;
  locked = true;
  answerA.disabled = true;
  answerB.disabled = true;
  if (choice === questions[index].correct) {
    score += 1;
    scoreEl.textContent = String(score);
  }
}

answerA.addEventListener("click", () => answer("a"));
answerB.addEventListener("click", () => answer("b"));

nextBtn.addEventListener("click", () => {
  if (finished) return;
  if (!locked) return;
  if (index === 0) {
    index = 1;
    render();
  } else {
    finished = true;
    questionEl.textContent = "Finished";
    answerA.disabled = true;
    answerB.disabled = true;
  }
});

restartBtn.addEventListener("click", () => {
  index = 0;
  score = 0;
  render();
});

render();
